// ─── Helpers ──────────────────────────────────────────────────────────────────

function uid(n: number) {
  return `00000000-0000-4000-8000-${String(n).padStart(12, '0')}`
}

function daysAgo(n: number) {
  return Date.now() - n * 86_400_000
}

